
import { motion, AnimatePresence } from 'framer-motion';
import { Lock, User } from 'lucide-react';
import { useVoiceInput } from '@/hooks/useVoiceInput';
import { VoiceAnswer } from './VoiceAnswer';

interface InterviewModalProps {
    isOpen: boolean;
    question: string | null;
    onValidate: (answer: string) => void;
    feedback: string | null;
    isProcessing: boolean;
}

export function InterviewModal({ isOpen, question, onValidate, feedback, isProcessing }: InterviewModalProps) {
    const { isListening, transcript, startListening, stopListening } = useVoiceInput();

    const handleSubmit = () => {
        onValidate(transcript);
        // We generally shouldn't clean transcript immediately in case of retry, but usually good ux
    };

    return (
        <AnimatePresence>
            {isOpen && (
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4"
                >
                    <motion.div
                        initial={{ scale: 0.9, y: 20 }}
                        animate={{ scale: 1, y: 0 }}
                        className="bg-zinc-900 border border-red-500/30 w-full max-w-2xl rounded-2xl shadow-2xl overflow-hidden"
                    >
                        {/* Header */}
                        <div className="bg-red-500/10 border-b border-red-500/20 p-6 flex flex-col items-center text-center">
                            <div className="w-12 h-12 bg-red-500/20 rounded-full flex items-center justify-center text-red-400 mb-4">
                                <User size={24} />
                            </div>
                            <h2 className="text-2xl font-bold text-white mb-2">INTERRUPTION</h2>
                            <p className="text-red-300 font-mono text-lg">{question}</p>
                        </div>

                        {/* Body - Voice Answer */}
                        <div className="p-8 flex flex-col items-center">
                            <VoiceAnswer
                                transcript={transcript}
                                isListening={isListening}
                                startListening={startListening}
                                stopListening={stopListening}
                                onSubmit={handleSubmit}
                                isProcessing={isProcessing}
                            />

                            {feedback && (
                                <div className="mt-6 p-4 bg-red-950/50 border border-red-900/50 rounded-lg text-red-200 text-sm">
                                    <span className="font-bold block mb-1">Feedback:</span>
                                    {feedback}
                                </div>
                            )}

                            <div className="mt-8 flex items-center gap-2 text-zinc-500 text-xs uppercase tracking-wider">
                                <Lock size={12} /> Editor Locked
                            </div>
                        </div>
                    </motion.div>
                </motion.div>
            )}
        </AnimatePresence>
    );
}
